/// <summary>
/// Creates a <c>METCustomerCreatedUpdatedBusinessEventContract</c> from a <c>CustTable</c> record.
/// </summary>
/// <param name = "_custTable">A <c>CustTable</c> record.</param>
/// <param name = "_dataEventType">A data event type.</param>
/// <returns>A <c>METCustomerCreatedUpdatedBusinessEventContract</c>.</returns>
public static METCustomerCreatedUpdatedBusinessEventContract newFromCustTable(CustTable  _custTable, DataEventType _dataEventType)
{
    METCustomerCreatedUpdatedBusinessEventContract contract = new METCustomerCreatedUpdatedBusinessEventContract();
    contract.initialize(_custTable, _dataEventType);
    return contract;
}

/// <summary>
/// Initializes the data members
/// </summary>
/// <param name = "_custTable">the customer record</param>
private void initialize(CustTable  _custTable, DataEventType _dataEventType)
{
    custAccount = _custTable.AccountNum;
    custOperGroupId = _custTable.METCustOperGroupId;
    dataEventType = _dataEventType;
}

[DataMember('CustomerAccount'), BusinessEventsDataMember("@AccountsReceivable:CustomerAccount")]
public CustAccount parmCustomerAccount(CustAccount _custAccount = custAccount)
{
    custAccount = _custAccount;

    return custAccount;
}

[DataMember('CustomerOpererationsGroupId'), BusinessEventsDataMember("@MET:METCustomerOperGroup")]
public METCustOperGroupId parmCustOperGroupId(METCustOperGroupId _custOperGroupId = custOperGroupId)
{
    custOperGroupId = _custOperGroupId;

    return custOperGroupId;
}

[DataMember('DataEventType'), BusinessEventsDataMember("@MET:DataEventType")]
public DataEventType parmDataEventType(DataEventType _dataEventType = dataEventType)
{
    dataEventType = _dataEventType;

    return dataEventType;
}
